windowclass.script:
local tQueue = {};
function addText(s)
	if text.getValue() ~= "" then
		table.insert(tQueue, s);
	else
		text.setValue(s);
	end
	self.updateNextButton();
end
function onNextPressed()
	if #tQueue > 0 then
		text.setValue(tQueue[1]);
		table.remove(tQueue, 1);
		self.updateNextButton();
	else
		parentcontrol.destroy();
	end
end
function updateNextButton()
	if #tQueue > 0 then
		next.setIcons("button_toolbar_arrow_e");
		next.setTooltipText(Interface.getString("tooltip_page_next"));
	else
		next.setIcons("button_toolbar_window_close");
		next.setTooltipText(Interface.getString("button_toolbar_window_close"));
	end
end

buttoncontrol.script:
function onInit()
	setColor(ColorManager.getWindowMenuIconColor());
end
function onButtonPress()
	window.onNextPressed();
end
